<?php
require __DIR__.'/../includes/modules.php';$user=require_role('admin');$error='';$edit=[];
if(isset($_GET['edit'])){$edit=query_rows('SELECT * FROM departments WHERE id=?',[record_id($_GET['edit'])])[0]??null;if(!$edit)missing();}
if(post()){check_csrf();try{
 $id=empty($_POST['id'])?null:record_id($_POST['id']);$action=$_POST['action']??'';
 db()->beginTransaction();
 if($id){$old=query_rows('SELECT * FROM departments WHERE id=? FOR UPDATE',[$id])[0]??null;if(!$old){db()->rollBack();missing();}}
 if($action==='delete'){if(!$id)throw new InvalidArgumentException('Choose a department.');if(query_rows("SELECT id FROM users WHERE department=? LIMIT 1",[$old['name']]))throw new InvalidArgumentException('Reassign employees before deleting this department.');execute_sql('DELETE FROM departments WHERE id=?',[$id]);}
 elseif($action==='save'){$name=text_value('name',100);$description=text_value('description',1000,false);if($id){execute_sql('UPDATE departments SET name=?,description=? WHERE id=?',[$name,$description,$id]);execute_sql('UPDATE users SET department=? WHERE department=?',[$name,$old['name']]);}else execute_sql('INSERT INTO departments (name,description) VALUES (?,?)',[$name,$description]);}
 else throw new InvalidArgumentException('Invalid action.');db()->commit();flash('Department saved.');redirect('admin/departments.php');
 }catch(InvalidArgumentException|PDOException $e){if(db()->inTransaction())db()->rollBack();if($e instanceof PDOException && $e->getCode()!=='23000')throw $e;$error=$e instanceof PDOException?'Department name already exists.':$e->getMessage();$edit=$_POST;}}
page_start('Departments',$user);error_notice($error);
?><section class="card"><h2>Add / Edit Department</h2><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><?php input_field('name','Department name',$edit['name']??'');input_field('description','Description',$edit['description']??'','text',false);?><div class="actions"><button class="btn btn-primary" name="action" value="save">Save Department</button><a class="btn btn-secondary" href="departments.php">Cancel</a></div></form></section><section class="card"><table class="table"><thead><tr><th>Department</th><th>Description</th><th>Employees</th><th>Actions</th></tr></thead><tbody><?php $rows=query_rows("SELECT d.*,(SELECT COUNT(*) FROM users u WHERE u.department=d.name AND u.role='employee') AS total FROM departments d ORDER BY name");foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['description'])?></td><td><?=h($r['total'])?></td><td><div class="actions"><a class="btn btn-primary" href="?edit=<?=$r['id']?>">Edit</a><?php delete_form((int)$r['id']);?></div></td></tr><?php endforeach;if(!$rows)echo '<tr><td colspan="4">No departments yet.</td></tr>';?></tbody></table></section><?php page_end();
